import { categories, events, ticketTypes } from "../schema";
import { slugify } from "../../modules/event/lib/event-slug";
import { EVENT_CATEGORIES } from "../../modules/event/types/event";
import { EVENT_DETAILS } from "./data/event-details";
import { EVENTS } from "./data/events";
import { MAX_TICKETS_PER_ZONE, VENUE_LAYOUTS } from "./data/venues";

type CategoryRow = typeof categories.$inferInsert;
// Foreign keys are resolved by slug at insert time (the ids are generated by the DB).
type EventRow = Omit<typeof events.$inferInsert, "categoryId" | "publishedAt"> & { categorySlug: string };
type TicketTypeRow = Omit<typeof ticketTypes.$inferInsert, "eventId"> & { eventSlug: string };

export const GENERAL_ADMISSION_CAPACITY = 1000;
// Se vende por zona y cantidad (sin butacas): las zonas numeradas del mock entran con un cupo fijo.
export const NUMBERED_ZONE_CAPACITY = 500;

const roundTo5 = (n: number) => Math.round(n / 5) * 5;

export { slugify };

// The mock dates are fixed, so some may already be gone: those move forward whole years until their (Lima) day is
// strictly after today. A fresh seed must never publish an event that already happened or that starts today.
const limaDay = new Intl.DateTimeFormat("en-CA", { timeZone: "America/Lima" });

export function ensureFuture(startsAt: Date, now: Date): Date {
  const endOfToday = new Date(`${limaDay.format(now)}T23:59:59.999-05:00`); // Lima has no DST
  const date = new Date(startsAt);
  while (date.getTime() <= endOfToday.getTime()) date.setUTCFullYear(date.getUTCFullYear() + 1);
  return date;
}

// `published_at` is left out on purpose: the CLI sets it on insert only.
// Each event gets one of `organizerIds` at random (`pick` is injectable so tests stay deterministic).
const randomPick = <T>(items: T[]): T => items[Math.floor(Math.random() * items.length)];

export async function buildSeedRows(organizerIds: string | string[], pick: <T>(items: T[]) => T = randomPick, now = new Date(), slugSuffix = "") {
  const organizers = [organizerIds].flat();
  const categoryRows: CategoryRow[] = EVENT_CATEGORIES.map((name, i) => ({ slug: slugify(name), name, sortOrder: i }));
  const eventRows: EventRow[] = [];
  const ticketTypeRows: TicketTypeRow[] = [];
  const skipped: { id: string; reason: string }[] = [];

  for (const summary of [...EVENTS].sort((a, b) => a.date.localeCompare(b.date))) {
    const details = EVENT_DETAILS[summary.id];
    if (!details) {
      skipped.push({ id: summary.id, reason: "no event details" });
      continue;
    }
    const event = { ...summary, ...details };
    if (event.currency !== "PEN") {
      skipped.push({ id: event.id, reason: `currency ${event.currency} not supported (PEN only)` });
      continue;
    }

    const slug = slugify(slugSuffix ? `${event.title} ${slugSuffix}` : event.title);
    eventRows.push({
      organizerId: pick(organizers),
      categorySlug: slugify(event.category),
      slug,
      title: event.title,
      description: event.description,
      coverImageUrl: event.image,
      // Lima has no DST: fixed -05:00.
      startsAt: ensureFuture(new Date(`${event.date}T${event.startTime}:00-05:00`), now),
      venueName: event.venue,
      address: event.address,
      city: event.city,
      status: "published",
    });

    VENUE_LAYOUTS[event.venueLayoutId].zones.forEach((zone, i) => {
      ticketTypeRows.push({
        eventSlug: slug,
        name: zone.name,
        priceCents: roundTo5(event.priceFrom * zone.priceFactor) * 100,
        // Nothing is sold at seed time, so even mock "sold-out" zones start with their full capacity.
        capacity: zone.kind === "numbered" ? NUMBERED_ZONE_CAPACITY : GENERAL_ADMISSION_CAPACITY,
        maxPerOrder: MAX_TICKETS_PER_ZONE,
        sortOrder: i,
      });
    });
  }

  return { categories: categoryRows, events: eventRows, ticketTypes: ticketTypeRows, skipped };
}
